        Item stored = repository.save(new Item(UUID.fromString("00000000-0000-0000-0000-000000000001"), ownerRow.id(), "sample", Instant.parse("2026-01-01T00:00:00Z")));

        assertThat(repository.findById(stored.id())).contains(stored);
        assertThat(repository.findAll()).contains(stored);
        assertThat(repository.deleteById(stored.id())).isTrue();
        assertThat(repository.findById(stored.id())).isEmpty();
        // A second delete is not a failure: the row is already gone, which is
        // what the caller asked for, and it is `false` rather than an error.
        assertThat(repository.deleteById(stored.id())).isFalse();
